2033:         let Some(stem) = path.file_stem().and_then(|s| s.to_str()) else {
2034:             continue;
2035:         };
2036:         let text = std::fs::read_to_string(&path).unwrap_or_default();
2037:         out.insert(stem.to_string(), text);
2038:     }
