2066: fn function_banner_matches(text: &str, candidate: &str) -> bool {
2067:     text.lines().any(|line| {
2068:         let trimmed = line.trim();
2069:         let Some(comment) = trimmed
2070:             .strip_prefix("/*")
2071:             .or_else(|| trimmed.strip_prefix("//"))
2072:         else {
2073:             return false;
2074:         };
2075:         let Some(rest) = comment.trim_start().strip_prefix("Function:") else {
2076:             return false;
2077:         };
2078:         let Some((name, _metadata)) = rest.trim().split_once('|') else {
2079:             return false;
2080:         };
2081:         name.trim() == candidate
2082:     })
2083: }
